const body = $input.first().json.body ?? $input.first().json;

const required = ['id', 'content', 'collection', 'project', 'topic'];
for (const field of required) {
  if (!body[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

const cleanContent = body.content
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ── Contextual Retrieval prepend (Anthropic 2024) ─────────────────────────
// Dense embedding is computed over embed_content, which prepends document
// metadata so the vector captures provenance (project, type, topic, tags,
// date). Original `content` is stored untouched in the payload and used for
// sparse vector + LLM consumption — the prepend never leaks to consumers.
// Anthropic benchmark: 35-49% retrieval failure reduction vs raw embedding.
const tagsStr = Array.isArray(body.tags)
  ? body.tags.join(', ')
  : (body.tags || '');
const chunkType = body.session_type || body.chunk_type || 'unknown';
const embed_content =
  `This chunk is from project ${body.project}, ` +
  `type ${chunkType}, topic "${body.topic}", ` +
  `tagged ${tagsStr}. Session date ${body.date || 'unknown'}. ` +
  `Content: ${cleanContent}`;

return [{
  json: {
    ...body,
    content: cleanContent,
    embed_content: embed_content,
    ingested_at: new Date().toISOString()
  }
}];

const embedding = $input.first().json.embedding;
const payload = $('Validate & Clean').first().json;

if (!embedding || !Array.isArray(embedding) || embedding.length !== 768) {
  throw new Error('Invalid embedding: expected 768 floats, got ' + (embedding ? embedding.length : 'null'));
}

// Hash string ID → numeric ID for Qdrant
const strId = payload.id;
let numId = 0;
for (let i = 0; i < strId.length; i++) {
  numId = ((numId << 5) - numId) + strId.charCodeAt(i);
  numId = numId & numId;
}
numId = Math.abs(numId);

// ── Sparse BM25 using djb2 hash (consistent across n8n + RAG Gateway) ──────
// Qdrant REST PUT /points does NOT support server-side document inference.
// We generate sparse {indices, values} client-side using djb2 hash,
// matching the same tokenizer used in QdrantVectorSearchClient.cs.
function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h) + str.charCodeAt(i);
    h = h & 0x7FFFFFFF; // keep positive 31-bit
  }
  return h;
}

const sparseText = `${payload.topic || ''} ${payload.content}`.trim();
const tokens = sparseText.toLowerCase().match(/[a-z0-9]+/g) || [];
const tf = {};
for (const t of tokens) { tf[t] = (tf[t] || 0) + 1; }

const sparseIndices = [];
const sparseValues  = [];
for (const [term, freq] of Object.entries(tf)) {
  sparseIndices.push(djb2(term));
  sparseValues.push(freq);
}

// ── Status field: default 'implemented' unless explicit override (e.g. 'planned') ─
const ALLOWED_STATUS = ['implemented', 'planned', 'deprecated'];
const rawStatus = (payload.status || '').toString().trim().toLowerCase();
const status = ALLOWED_STATUS.includes(rawStatus) ? rawStatus : 'implemented';

// ── Pre-build upsert body here (avoids n8n expression serialization quirks) ─
const upsertBody = JSON.stringify({
  points: [{
    id: numId,
    vector: {
      dense: embedding
    },
    ...(sparseIndices.length > 0 ? {
      sparse_vectors: {
        sparse: { indices: sparseIndices, values: sparseValues }
      }
    } : {}),
    payload: {
      string_id:    payload.id,
      doc_id:       payload.doc_id      || payload.id,
      date:         payload.date        || '',
      source:       payload.source      || 'claude-code',
      project:      payload.project     || 'unknown',
      topic:        payload.topic       || '',
      filename:     payload.filename    || '',
      chunk_num:    payload.chunk_num   || 1,
      content:      payload.content,
      ingested_at:  payload.ingested_at,
      tags:         payload.tags         || '',
      session_type: payload.session_type || '',
      environment:  payload.environment  || '',
      git_branch:   payload.git_branch   || '',
      related:      payload.related      || '',
      chunk_type:   payload.session_type || '',
      status:       status
    }
  }]
});

return [{
  json: {
    qdrant_id:    numId,
    upsert_body:  upsertBody,
    // fields below used by Build Response node
    string_id:    payload.id,
    doc_id:       payload.doc_id      || payload.id,
    project:      payload.project     || 'unknown',
    topic:        payload.topic       || '',
    chunk_num:    payload.chunk_num   || 1,
    session_type: payload.session_type || '',
    environment:  payload.environment  || '',
    git_branch:   payload.git_branch   || '',
    tags:         payload.tags         || '',
    ingested_at:  payload.ingested_at,
    sparse_terms: sparseIndices.length,
    status:       status
  }
}];

const qdrantResult = $input.first().json;
const point = $('Prepare Qdrant Point').first().json;

return [{
  json: {
    status:       'ok',
    payload_status: point.status,
    qdrant_id:    point.qdrant_id,
    string_id:    point.string_id,
    project:      point.project,
    topic:        point.topic,
    chunk_num:    point.chunk_num,
    session_type: point.session_type,
    environment:  point.environment,
    git_branch:   point.git_branch,
    tags:         point.tags,
    collection:   'knowledge_v2',
    ingested_at:  point.ingested_at
  }
}];
